package com.civicconnect.model;

import jakarta.persistence.*;

import java.time.OffsetDateTime;
import java.util.UUID;

/**
 * An in-app notification delivered to a specific user.
 *
 * <p>Notifications are generated by the service layer when key events occur
 * (e.g. status change, department assignment, resolution). They are surfaced
 * to the user via the {@code GET /api/v1/notifications} endpoint and can be
 * individually or batch-marked as read.
 *
 * <p>Table: {@code notifications}
 */
@Entity
@Table(name = "notifications", indexes = {
        @Index(name = "idx_notifications_user_id", columnList = "user_id"),
        @Index(name = "idx_notifications_unread",  columnList = "user_id")
})
public class Notification {

    @Id
    @GeneratedValue(strategy = GenerationType.UUID)
    @Column(name = "id", nullable = false, updatable = false)
    private UUID id;

    /**
     * Recipient of the notification. Null for broadcast/system notifications
     * (reserved for future use; currently always set to a specific user).
     */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "user_id")
    private User user;

    /** The complaint this notification relates to. May be null for system alerts. */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "complaint_id")
    private Complaint complaint;

    /**
     * Short type tag used to render the correct icon or action in the UI.
     * Examples: {@code STATUS_UPDATE}, {@code ASSIGNED}, {@code RESOLVED},
     * {@code REJECTED}, {@code REOPENED}.
     */
    @Column(name = "notification_type", nullable = false, length = 50)
    private String notificationType;

    /** Human-readable notification text shown to the user. */
    @Column(name = "message", nullable = false, columnDefinition = "TEXT")
    private String message;

    /** False until the user views or explicitly dismisses the notification. */
    @Column(name = "is_read", nullable = false)
    private boolean read = false;

    @Column(name = "created_at", nullable = false, updatable = false)
    private OffsetDateTime createdAt = OffsetDateTime.now();

    // ── Constructors ─────────────────────────────────────────────────────────

    protected Notification() {
        // Required by JPA
    }

    public Notification(User user,
                        Complaint complaint,
                        String notificationType,
                        String message) {
        this.user             = user;
        this.complaint        = complaint;
        this.notificationType = notificationType;
        this.message          = message;
    }

    // ── Getters ──────────────────────────────────────────────────────────────

    public UUID getId() { return id; }
    public User getUser() { return user; }
    public Complaint getComplaint() { return complaint; }
    public String getNotificationType() { return notificationType; }
    public String getMessage() { return message; }
    public boolean isRead() { return read; }
    public OffsetDateTime getCreatedAt() { return createdAt; }

    // ── Setters ──────────────────────────────────────────────────────────────

    public void setRead(boolean read) { this.read = read; }

    // ── Object methods ───────────────────────────────────────────────────────

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Notification that)) return false;
        return id != null && id.equals(that.id);
    }

    @Override
    public int hashCode() {
        return id != null ? id.hashCode() : 0;
    }
}
